#define T(t, d) tanh(cos(iTime * t) * d + d - 2.)
#define C(a, e) cross(a, e).z
#define L(a, b) 1. - 250. * abs(C(a, b)) / length(b - a) 
#define hex(i) u - (T(2.1, 4.) * .3 + .2) * cos(i * pi / 6. + T(1., 5.) + vec3(0, 11, 0))
#define pi acos(-1.)

void mainImage(out vec4 o, vec2 U) {
    vec3 r = iResolution,
         u, a, b;
         u = (U.xyy - r / 2.) / r.y;

    o = vec4(0);

    for(float i; i < 48.; i += 2.){
        a = hex(i);
        b = hex(i+1.);
        o = max(o, L(a, b));
        o = mix(o, vec4(1, 0, 0, 0), smoothstep(10. / r.y, .0, length(a.xy)));
    }
}
